import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"FETV: A Benchmark for Fine-Grained Evaluation of Open-Domain Text-to-Video Generation","description":"","frontmatter":{"title":"FETV: A Benchmark for Fine-Grained Evaluation of Open-Domain Text-to-Video Generation","arxiv":"2311.01813","date":"2023-11-03","authors":"Yuanxin Liu, Lei Li, Shuhuai Ren, Rundong Gao, Shicheng Li, Sishuo Chen, Xu Sun, Lu Hou","categories":"cs.CV","topics":"视频生成评测, 细粒度分类体系, 自动指标可靠性","outline":[2,2]},"headers":[],"relativePath":"papers/2311.01813.md","filePath":"papers/2311.01813.md","lastUpdated":null}'),e={name:"papers/2311.01813.md"};function l(r,s,i,m,o,c){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="fetv-a-benchmark-for-fine-grained-evaluation-of-open-domain-text-to-video-generation" tabindex="-1">FETV: A Benchmark for Fine-Grained Evaluation of Open-Domain Text-to-Video Generation <a class="header-anchor" href="#fetv-a-benchmark-for-fine-grained-evaluation-of-open-domain-text-to-video-generation" aria-label="Permalink to &quot;FETV: A Benchmark for Fine-Grained Evaluation of Open-Domain Text-to-Video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2311.01813" target="_blank" rel="noreferrer">2311.01813</a></td></tr><tr><td><strong>提交日期</strong></td><td>2023-11-03</td></tr><tr><td><strong>作者</strong></td><td>Yuanxin Liu, Lei Li, Shuhuai Ren, Rundong Gao, Shicheng Li, Sishuo Chen, Xu Sun, Lu Hou</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用「主要内容 × 受控属性 × prompt 复杂度」三个正交维度（前两者都拆出<strong>时序</strong>子类）给 619 条 prompt 打多标签，把 T2V 评测切成可比较的细粒度子集，再以人工评分为参照系逐类诊断自动指标，最终用 UMT 换掉 CLIP/I3D 得到 UMTScore 与 FVD-UMT。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/post-training-rl">后训练与强化学习</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文按 <strong>v3</strong>（2023-12-26 修订）全文撰写，v1 提交于 2023-11-03，frontmatter 日期取首次提交日。论文 comments 为 <strong>NeurIPS 2023 Datasets and Benchmarks Track</strong>，benchmark 页 github.com/llyx97/FETV。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>同期的 <a href="/notes/papers/2310.11440">EvalCrafter</a> 关心的是&quot;怎么把一堆指标汇总成一个可信的总分&quot;，FETV 问的是相反方向的问题：<strong>为什么要汇总</strong>。作者的判断是，报整个测试集上的一个总分只能给出模型能力的粗糙轮廓，真正有用的信息藏在&quot;它在哪类 prompt 上失手&quot;里。</p><p>已有 benchmark 的分类体系确实存在，但要么只按内容主题分（MSR-VTT 的 20 个类：music、sports、news），要么只按挑战类型分（DrawBench），而且<strong>全部忽略时间维度</strong>。这一点对视频生成是致命的：一个模型可能画得出&quot;一个人&quot;，但画不出&quot;一个人从左向右走&quot;；可能画得出&quot;一杯水&quot;，但画不出&quot;水被倒进杯子&quot;。用只描述空间内容的类别体系，这类失败会被平均掉。</p><p>第二个问题与 EvalCrafter 的诊断一致但更彻底：自动指标到底可不可信。T2I 领域已有多篇工作（Ding et al. 2022；Otani et al. 2023；Parmar et al. 2022）发现自动指标与人类不一致，T2V 侧当时还是空白。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>UCF-101 / Kinetics</strong>：为动作识别设计，是<strong>闭域</strong>的，覆盖不了开放域生成的内容多样性。它们有时序类别（动作），但没有开放性。</p><p><strong>MSR-VTT</strong>：开放域、有分类，但分类只考虑视频主题，既不管时序内容也不管 prompt 想控制什么属性。</p><p><strong>DrawBench / PartiPrompts</strong>：引入了&quot;挑战类型&quot;这个维度，是本文分类体系的直接灵感来源（本文的 78 条 unusual prompt 明确对标 PartiPrompts 的 Imagination 与 DrawBench 的 Conflicting），但 prompt 里没有时序描述。</p><p><strong>Make-a-Video-Eval</strong>：300 条专为 T2V 写的 prompt，但类别（animals / fantasy / people / nature and scenes / food and beverage）仍然只描述空间内容。</p><p><strong>自动指标侧</strong>：IS 只看&quot;内容可识别且多样&quot;；FID/FVD 算分布距离，需要参考视频集；CLIPScore 逐帧算图文相似度。本文表 1 用一张对照表把上述 benchmark 在六个格子（空间/时序 × 主要内容/受控属性 + 开放域 + 复杂度）上逐一打勾，FETV 是唯一全勾的。这种呈现方式很清楚，但也暴露了本文贡献的性质：<strong>它主要是一次分类体系的补全，而不是一个新机制</strong>。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从&quot;评测太粗&quot;这个不满出发，第一个决定是把 prompt 打上标签。但打什么标签？一个认真的研究者会先问：&quot;T2V 失败的模式有几种？&quot;</p><p>观察当时的失败案例可以归出两类彼此独立的东西。一类是<strong>内容</strong>难度：人脸和手指比云和水难画。另一类是<strong>可控性</strong>：prompt 说&quot;三只&quot;却画了五只，说&quot;向左&quot;却向右。这两类不是同一个轴——&quot;人在跑步&quot;既是内容难（高频细节）又可能是控制难（跑步的方向）。所以它们必须是正交的两个维度，而不是一个类别列表。</p><p>第三个维度来得更自然：prompt 越长越难，用非停用词个数分成三档即可。</p><p>真正的关键决定是<strong>每个维度都再切一刀成空间/时序</strong>。这一步的理由很实际：如果只有&quot;主要内容 = 人&quot;，那么&quot;人像静止画得好但人跑起来就崩&quot;这个事实无处可放。加上时序子类（actions、kinetic motions 等）之后，同一批视频可以从两个正交视角各看一遍，作者在 §4.3 明确说时序分类&quot;提供了更直接的时序视角&quot;。</p><p>最后一个决定是<strong>允许多标签</strong>。作者点名这一点比&quot;每条 prompt 只属于一个类&quot;的既有 benchmark 更贴近现实——一条 prompt 本来就可能同时想控制颜色和速度。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>模型的能力不是一个数，而是一张按&quot;内容难度 × 控制类型&quot;排布的地图；把 prompt 按这两个正交维度（且各自含时序子类）打上多标签，地图上的空洞就自己显形了。同一套标签还能反过来用：把人工评分当参照系，逐格算自动指标与人的相关性，就能知道每个指标在哪类场景下可信。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>Benchmark 构造。</strong> prompt 来自两处：MSR-VTT 测试集（59,800 对）与 WebVid 验证集（4,999 对）里挑出的 541 条，加上作者手写的 78 条 unusual prompt。后者按七种冲突类型枚举编写：object-action、object-object、object-color、object-quantity、object-direction、object-speed、event order，例如&quot;A cat is driving a car.&quot;。</p><p><strong>标注。</strong> 两步走：先用关键词表、WordNet synset 与手工匹配模式做自动打标（判断是否属于 animals 就遍历词、查是否落在动物 synset 里）；再人工复核。人工挑选的方式很讲究——枚举 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 组合，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 取 6 个受控属性类、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 取 4 个时序主要内容类，<strong>每个组合挑约 20 条</strong>，保证交叉格子都有样本，而不是让分布自然倾斜。对来自现有数据集的 prompt，还会修正那些与参考视频不符的描述。</p><p><strong>人工评测。</strong> 4 个模型：CogVideo（Transformer + VQVAE）、Text2Video-zero（无视频训练，纯靠给 SD latent 加运动动力学）、ModelScopeT2V（SD + 时序卷积/注意力，图文与视频文本联合训练）、ZeroScope（从 ModelScopeT2V 权重继续训、去水印、优化 16:9）。四个评价维度：静态质量、时序质量、整体对齐（均 1–5 Likert）、细粒度对齐（1–3 Likert）。每条视频 3 位实验室研究生打分取均值。标注一致性用 Krippendorff <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span>：<strong>0.711 / 0.770 / 0.638 / 0.653</strong>——前两项属于可接受区间，后两项（对齐类）明显偏低，说明&quot;对齐得好不好&quot;本身就比&quot;画质好不好&quot;更主观。总计 <strong>28,116</strong> 条评分。</p><p><strong>指标诊断。</strong> 图文对齐侧算五个指标与人工评分的样本级相关性；画质侧因为 FID/FVD 不是样本级指标，只能比<strong>系统级排序</strong>——每个模型每个类别生成 300 条视频，总体 FID/FVD 用 1024 条生成与参考视频、4 个随机种子取平均。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化主要在评测统计量上。</p><p><strong>Krippendorff&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span>。</strong> 定义为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">o</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">/</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">o</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是实际观测到的标注者分歧，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是在完全随机分派下的期望分歧。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 表示完全一致，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 表示与瞎猜无异。它比简单的一致率更合适，因为它对&quot;评分尺度&quot;和&quot;标注者缺席&quot;都稳健。本文的对齐类维度只有 0.638/0.653，意味着约三分之一的分歧无法用&quot;任务本身有确定答案&quot;来解释——<strong>这构成了自动指标相关性的天花板</strong>，也是表 2 最后一行&quot;Human&quot;存在的理由。</p><p><strong>Kendall&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。</strong> 一致对与不一致对之差再按可能的最大值归一化。选 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（而非 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">b</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）是因为人工评分只有 5 档或 3 档、平局极多，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 对<strong>行列类别数不等</strong>的情形做了修正。</p><p><strong>FVD 与 FVD-UMT。</strong> FVD 把两组视频经编码器映到特征空间，假设两侧特征服从高斯，算 Fréchet 距离</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8641em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">∥</span><span class="mord"><span class="mord mathnormal">μ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1502em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">μ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">∥</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">Tr</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord">Σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord">Σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.288em;vertical-align:-0.35em;"></span><span class="mord">2</span><span class="mopen">(</span><span class="mord"><span class="mord">Σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord">Σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.938em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1/2</span></span></span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>关键 intuition 是：<strong>这个式子本身没有任何&quot;质量&quot;的含义，全部语义都藏在编码器里</strong>。原始 FVD 用 I3D，一个在 Kinetics 上训动作分类的网络——它的特征对&quot;这段视频属于哪个动作类&quot;敏感，对&quot;画面有没有崩坏&quot;未必敏感。本文把编码器换成 UMT 的视觉编码器就得到 FVD-UMT。同一个公式、同一批视频，换个特征空间结论就变——这既是本文改进的来源，也是 FVD 这类指标的根本脆弱性所在。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：画质随内容怎么变？</strong> 空间上，含&quot;人&quot;和&quot;动物&quot;的视频质量差，含&quot;植物&quot;&quot;风景与自然物&quot;的好；作者的解释是前者含大量高频细节（人脸、手指），后者以低频信息为主（水、云）。时序上，&quot;actions&quot;与&quot;kinetic motions&quot;最差，同样归因于时序内容频率更高。四个模型<strong>没有一个</strong>接近真实视频的质量。Text2Video-zero 静态质量最好但时序质量远远垫底——它继承了 SD 的画图能力却完全没有视频训练。ZeroScope 从 ModelScopeT2V 训来，时序质量相当而静态质量更差，作者推测是因为它的优化目标是 16:9 与去水印而非画质。</p><p><strong>问题二：可控性随属性怎么变？</strong> &quot;颜色&quot;与&quot;相机视角&quot;多数情况已能控制；&quot;数量&quot;&quot;运动方向&quot;&quot;事件顺序&quot;四个模型全部失手。ModelScopeT2V 在&quot;速度&quot;与&quot;运动方向&quot;上表现出一点初步能力，CogVideo 与 Text2Video-zero 没有。prompt 复杂度与对齐度<strong>没有明显相关</strong>——只有 complex 档略低，作者如实写&quot;cannot observe a clear correlation&quot;。</p><p><strong>问题三：自动指标可信吗？</strong>（表 2，Kendall <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> / Spearman <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>，All 列）CLIPScore <strong>0.177/0.243</strong>；在 MSR-VTT 检索任务上微调过的 CLIPScore-ft 0.224/0.309；BLIPScore 0.235/0.322；把任务改写成 VQA 的 Otter-VQA 只有 <strong>0.081/0.114</strong>；UMTScore <strong>0.309/0.425</strong>。作为参照，<strong>人类之间</strong>的相关性是 <strong>0.576/0.719</strong>。也就是说最好的自动指标只达到人类一致性水平的约 54%（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 口径）。更重要的是图 8：CLIPScore-ft 与 BLIPScore 虽然样本级相关性提高了，<strong>却仍然给不出与人类一致的模型排序</strong>，只有 UMTScore 能。</p><p>一个反直觉的观察：UMTScore 在<strong>困难</strong>类别上相关性更高（Quantity 0.394/0.528、Motion Direction 0.356/0.476）而在简单类别上更低（Color 0.304/0.420、Camera View 0.300/0.415）。作者的解释是简单类别上各模型表现接近、难以区分，并明确标注为 conjecture。</p><p><strong>画质指标</strong>：FID 与原始 FVD 与人类感知&quot;loosely coupled&quot;，FVD-UMT 给出与人类一致的排序。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版。</strong> T2V 评测报一个总分会把最有价值的信息平均掉，FETV 用三个正交维度（且都含时序子类）给 619 条 prompt 打多标签，把评测切成可比较的细粒度子集。人工评测的结论很具体：模型在&quot;人/动物&quot;与&quot;动作/动力学运动&quot;上画质最差，在&quot;数量/运动方向/事件顺序&quot;上完全不可控，而颜色与相机视角已基本解决。指标诊断的结论更重要：CLIPScore 与人类的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 只有 0.177，人类之间是 0.576；FID 与原始 FVD 与人类感知只是松散耦合。把 CLIP 换成 UMT（UMTScore）、把 I3D 换成 UMT 视觉编码器（FVD-UMT）后相关性大幅提升，且能给出与人类一致的模型排序。把 VQA 范式直接套过来的 Otter-VQA 效果最差（0.081），说明&quot;用更强的通用模型&quot;不等于&quot;用对了模型&quot;。</p><p><strong>3 句话版。</strong> 给 prompt 打上正交的多标签，评测才能定位失败在哪一格。诊断结果是当时通用的自动指标基本不可信，换成视频-文本预训练的 UMT 之后才勉强能用。缺口仍然巨大：最好的自动指标只有人类一致性的一半。</p><p><strong>1 句话版。</strong> 别信 CLIPScore 和 FVD，也别指望换个大模型就自动变准。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是：<strong>UMTScore 的优势来自&quot;UMT 是更强的视频-文本模型&quot;这一因果解释</strong>。</p><p>这条因果解释是全文最重要的推广性主张——作者据此写下&quot;训练 VLM 时用视频数据很重要，T2V 评测能受益于更强 VLM 的发展&quot;。如果它不成立，那么 UMTScore 就只是一个恰好与本 benchmark 同域的指标，换一个 prompt 来源它可能立刻退化。</p><p>它为什么可能不成立：<strong>FETV 的 541 条 prompt 与全部参考视频来自 MSR-VTT 测试集与 WebVid 验证集，而本文采用的 UMT 恰恰是&quot;在 MSR-VTT 上微调过的版本&quot;</strong>（正文原话：we adopt the fine-tuned version on MSR-VTT）。同一段落里，CLIPScore-ft 也是&quot;在 MSR-VTT 视频-文本检索任务上微调的 CLIP&quot;，而它相对原始 CLIPScore 的提升同样明显（0.177→0.224）。于是&quot;是否在 MSR-VTT 上微调过&quot;与&quot;是否是更强的视频-文本模型&quot;这两个因素<strong>在实验设计中完全共线</strong>：表 2 里排前两位的方法恰好都被 MSR-VTT 微调过，排后面的 CLIPScore 与 Otter-VQA 都没有。<strong>这是基于证据的推断，不是论文的声明</strong>——论文把提升全部归因于模型能力，没有讨论域匹配这一可能。</p><p>论文提供的间接反证是 BLIPScore：它没有在 MSR-VTT 上微调，却也达到 0.235/0.322，略高于 CLIPScore-ft。这说明&quot;更强的 VLM&quot;确实有独立贡献。但 BLIPScore 与 UMTScore 之间还差着 0.074 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，这段差距归谁，现有实验分不开。</p><p>缺什么证据：一次<strong>跨域检验</strong>。用一批与 MSR-VTT/WebVid 都不同源的 prompt（例如本文自己写的 78 条 unusual prompt，或 Make-a-Video-Eval）单独算一遍表 2。如果 UMTScore 在 unusual 子集上的相关性显著低于整体，域匹配假说就得到支持。这批数据论文已经有了，只差一张表。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要重跑人工评测：</p><ul><li><strong>数据</strong>：直接用 FETV 公开的 619 条 prompt、类别标签与人工评分。</li><li><strong>实现</strong>：只实现 CLIPScore、BLIPScore、UMTScore 三个（都有现成权重），外加一个新增对照——<strong>未在 MSR-VTT 上微调的 UMT 版本</strong>（UMT 有公开的预训练权重）。</li><li><strong>核心操作</strong>：按 prompt 来源把评测集切成两块：<strong>来自 MSR-VTT/WebVid 的 541 条</strong> vs <strong>作者手写的 78 条 unusual prompt</strong>。在两块上分别重算表 2 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>。</li><li><strong>测量</strong>：四个指标 × 两个子集的相关性矩阵，以及 UMT-微调版与 UMT-预训练版之间的差值。</li><li><strong>判据</strong>：若 UMTScore 在 unusual 子集上的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 掉到 BLIPScore 的水平，且&quot;微调版减预训练版&quot;的增益在 541 条子集上远大于 78 条子集，则 §9 的域匹配假说成立，论文的推广性结论需要收窄；若两个子集上的排序与差值都稳定，则&quot;更强的视频-文本模型确实更可靠&quot;这一 claim 得到支持。</li><li><strong>成本控制</strong>：78 条子集样本量小，需要报 bootstrap 置信区间而非点估计。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>最强攻击点：画质指标的全部证据只是 4 个模型的排序一致。</strong> 正文明确写道，FID 与 FVD 不是样本级指标，&quot;we cannot calculate the correlation coefficients&quot;，因此只能比系统级排名。4 个模型的全序共 24 种，随机命中的概率约 4%；而 FID/FVD 也并非完全乱序（正文用的是 loosely coupled 而非 uncorrelated）。<strong>这是一个统计功效极低的检验</strong>：FVD-UMT 排对了，可能只是它在一次 4 选 1 的比较中运气好。要把这条结论坐实，至少需要把模型数扩到十几个，或者构造合成的退化梯度（对同一批视频施加不同强度的噪声/闪烁/模糊，看 FVD-UMT 是否单调响应）——后者一周内就能做，且不需要新模型。</p><p><strong>第二个攻击点：被对齐的那个&quot;人类画质排序&quot;本身是可疑的聚合量。</strong> 图 10 比较的是 FID/FVD/FVD-UMT 与&quot;人类画质（静态与时序质量的平均）&quot;的排序。但论文自己在 §4.3 明确指出，这两者在 Text2Video-zero 上<strong>剧烈分离</strong>——静态最好、时序垫底。把两个已知会分离的量取算术平均得到一个排序，再用它当作 ground truth 去验证指标，逻辑上并不稳固。一个干净的替代做法是分别对静态质量与时序质量各验一次；若 FVD-UMT 只在其中一个上对得上，结论就要相应收窄。</p><p><strong>第三个观察：Otter-VQA 的失败是一条被低估的负面结果。</strong> 把对齐评测改写成 VQA（用 Vicuna 从 prompt 抽关键元素生成 yes/no 问题，再让 Video LLM 回答）只拿到 0.081/0.114，是全表最低，甚至低于原始 CLIPScore。这条结果在当时是反直觉的——毕竟同期的 T2I 评测（TIFA）正是靠 VQA 取得成功，<a href="/notes/papers/2310.11440">EvalCrafter</a> 也在用 BLIP2 生成 caption 做对齐。它提示 2023 年的 Video LLM 对生成视频这种分布外输入的鲁棒性远不足以充当评判者。论文只用一句话带过，没有分析失败原因（是问题生成的质量、还是 Video LLM 的视频理解、还是 yes/no 输出的校准）。</p><p><strong>一处需要核对的计数不一致：</strong> §4.1 明确列出<strong>四个</strong>模型，§4.2 的实现细节却写 &quot;We generate three videos for each prompt using the three models respectively&quot;，并给出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">619</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">16</span><span class="mord"><span class="mpunct">,</span></span><span class="mord">713</span></span></span></span> 的计数——这个算式里模型数是 <strong>3</strong> 而非 4。推测 v1 版本只评了三个模型（ZeroScope 是后续版本补的），而这段计数文字未随之更新。这不影响主要结论，但意味着&quot;28,116 条评分&quot;这个总数与四模型的设定对不上，引用时需注意。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>把 benchmark 从&quot;一组固定 prompt&quot;变成&quot;一个可主动查询的能力探针&quot;。</strong></p><p>(a) <strong>驱动它的局限</strong>：FETV 的核心洞察是&quot;模型的能力是一张地图&quot;，但它的实现仍然是一张<strong>静态的、均匀采样的</strong>地图——每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 组合挑约 20 条 prompt，不管这个格子对当前模型是否有区分度。结果是大量预算花在了早已饱和的格子上（颜色、相机视角四个模型都能做），而真正有信息量的边界区域（数量控制从&quot;能&quot;到&quot;不能&quot;的临界点在哪：3 个物体？5 个？）只有一个二值结论&quot;全部失手&quot;。§7 提到 UMTScore 在难类别上相关性更高、在简单类别上更低，正是&quot;简单格子已无区分度&quot;的直接证据——<strong>benchmark 自己在告诉我们它的一半样本是浪费的</strong>。</p><p>(b) <strong>可借鉴的邻域工具</strong>：心理物理学的 <strong>adaptive staircase / QUEST</strong> 方法，以及主动学习里的<strong>不确定性采样</strong>。心理物理学要测的正是同类问题——找出某个感知维度上的阈值，而不是在整个范围上均匀测。它的标准做法是根据被试上一次的反应动态调整下一个刺激的强度，用几十次试验就能定位阈值，比均匀采样高效一到两个数量级。</p><p>(c) <strong>第一个实验</strong>：选&quot;数量控制&quot;这一个属性做验证。把 prompt 参数化为&quot;<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 只 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>&quot;，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 从 1 到 8。先用固定的均匀采样（每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 取 20 条）测出四个模型的 Count 准确率曲线作为真值，成本约 640 条视频。然后实现一个 staircase：从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 开始，答对就加一、答错就减一，只跑 40 条视频，看能否复原出同一条曲线的阈值点（准确率跌破 50% 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span>）。若 40 条能逼近 640 条的结论，那么整套 FETV 的评测成本可以压缩一个数量级，且输出从&quot;该模型数量控制得分 0.42&quot;升级成&quot;该模型在 3 个以内可靠、4 个开始崩&quot;——后者才是模型开发者真正能用的信息。这个 framing 的野心不在于省钱，而在于把 benchmark 的输出从<strong>标量</strong>换成<strong>能力边界的位置</strong>。</p>',63)])])}const u=a(e,[["render",l]]);export{g as __pageData,u as default};
